def flatten(items, depth=None):
    """Flattens nested lists into one list.

    depth is the number of nesting levels to remove. None flattens completely,
    0 returns a shallow copy. A negative depth raises ValueError.
    Strings are never split.
    """
    if depth is not None and depth < 0:
        raise ValueError("depth must be non-negative or None")
    out = []
    for item in items:
        if isinstance(item, list) and (depth is None or depth > 0):
            out.extend(flatten(item, None if depth is None else depth - 1))
        else:
            out.append(item)
    return out

files.tests/test_nested.py:
from nested import flatten


def test_flattens_completely():
    assert flatten([1, [2, [3, [4]]]]) == [1, 2, 3, 4]


def test_flat_list_unchanged():
    assert flatten([1, 2, 3]) == [1, 2, 3]


def test_depth_one():
    assert flatten([1, [2, [3, [4]]]], depth=1) == [1, 2, [3, [4]]]


def test_depth_two():
    assert flatten([1, [2, [3, [4]]]], depth=2) == [1, 2, 3, [4]]


def test_depth_zero_returns_copy():
    src = [1, [2]]
    out = flatten(src, depth=0)
    assert out == [1, [2]]
    assert out is not src


def test_depth_none_flattens_fully():
    assert flatten([1, [2, [3, [4]]]], depth=None) == [1, 2, 3, 4]


def test_negative_depth_raises():
    import pytest
    with pytest.raises(ValueError):
        flatten([1, [2]], depth=-1)


def test_strings_not_split():
    assert flatten(["ab", ["cd"]]) == ["ab", "cd"]
    assert flatten(["ab", ["cd"]], depth=1) == ["ab", "cd"]

